#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=6
ENV_FILE=/dev/null   # nothing here belongs in the app's .env
cd "$(dirname "${BASH_SOURCE[0]}")/.."
KEY_DIR=$(mktemp -d)
trap 'rm -rf "$KEY_DIR"' EXIT

banner "piano-estv : déploiement automatique"

# ──────────────────────────────────────────────────────────────────────────
stage "Vérifier cet ordinateur"
for tool in git ssh ssh-keygen gh; do
  command -v "$tool" >/dev/null || { warn "$tool n'est pas installé."; exit 1; }
done
gh auth status >/dev/null 2>&1 || { warn "GitHub CLI n'est pas connecté : lance « gh auth login », puis relance."; exit 1; }
REPO_NAME=$(gh repo view --json nameWithOwner -q .nameWithOwner)
say "Dépôt GitHub : $REPO_NAME"
git fetch --quiet origin main
if ! git cat-file -e origin/main:deploy/deploy.sh 2>/dev/null || ! git cat-file -e origin/main:.github/workflows/deploy.yml 2>/dev/null; then
  warn "La CI/CD n'est pas encore sur GitHub (branche main)."
  step "Commite et pousse tout, puis relance cet assistant."
  note "Tant que tu n'as pas fini, la CI lance les tests mais ne déploie rien."
  exit 1
fi
pause "Tout est là. Entrée pour continuer"

# ──────────────────────────────────────────────────────────────────────────
stage "Trouver le projet sur le VPS"
say "Il faut l'adresse du VPS et l'utilisateur qui fait tes « docker compose » aujourd'hui."
note "Exemple : si tu te connectes avec « ssh deploy@1.2.3.4 », l'adresse est 1.2.3.4 et l'utilisateur deploy."
ask VPS_IP "Adresse du VPS :"
ask VPS_USER "Utilisateur SSH :"
ask VPS_PORT "Port SSH (Entrée = 22) :"
VPS_PORT="${VPS_PORT:-22}"
on_vps() { ssh -p "$VPS_PORT" -o ConnectTimeout=15 "$VPS_USER@$VPS_IP" "$@"; }
say "Connexion avec ta clé habituelle…"
on_vps true || { warn "Connexion impossible : vérifie que « ssh -p $VPS_PORT $VPS_USER@$VPS_IP » marche, puis relance."; exit 1; }
on_vps 'docker compose version >/dev/null && command -v git >/dev/null && command -v flock >/dev/null' \
  || { warn "Cet utilisateur ne peut pas lancer docker compose (ou git / flock manque)."; exit 1; }
DIR=$(on_vps "docker inspect -f '{{index .Config.Labels \"com.docker.compose.project.working_dir\"}}' piano-backend-estv" 2>/dev/null || true)
if [[ -z "$DIR" ]]; then
  warn "Conteneur piano-backend-estv introuvable."
  ask DIR "Dossier du projet sur le VPS (chemin complet) :"
fi
[[ "$DIR" =~ ^/[A-Za-z0-9._/-]+$ ]] || { warn "Chemin inattendu : $DIR"; exit 1; }
say "Projet : $DIR"
[[ "$(on_vps "git -C $DIR branch --show-current")" == main ]] || { warn "Le dépôt du VPS n'est pas sur main."; exit 1; }
CHANGES=$(on_vps "git -C $DIR status --porcelain --untracked-files=no")
if [[ -n "$CHANGES" ]]; then
  warn "Des fichiers suivis ont été modifiés à la main sur le VPS :"
  printf '%s\n' "$CHANGES"
  step "Règle ça d'abord (git diff, git checkout -- <fichier>), puis relance."
  exit 1
fi
on_vps "git -C $DIR fetch --quiet origin main" || { warn "Le VPS n'arrive pas à lire le dépôt GitHub (git fetch)."; exit 1; }
pause "Le VPS est prêt. Entrée pour continuer"

# ──────────────────────────────────────────────────────────────────────────
stage "Récupérer le script de déploiement sur le VPS"
say "Le VPS passe au dernier commit de main. Le site en ligne ne change pas encore :"
say "seuls les fichiers sont mis à jour, les conteneurs tournent toujours."
confirm "Lancer « git merge --ff-only » dans $DIR ?" || exit 1
on_vps "git -C $DIR merge --quiet --ff-only FETCH_HEAD && test -x $DIR/deploy/deploy.sh" \
  || { warn "Échec : le VPS a peut-être des commits à lui."; exit 1; }
pause "Fait. Entrée pour continuer"

# ──────────────────────────────────────────────────────────────────────────
stage "Créer la clé de déploiement"
say "Une clé SSH neuve, qui ne sait faire qu'UNE chose sur le VPS : déployer un"
say "commit de main. Même volée, elle ne donne ni terminal, ni fichiers."
ssh-keygen -q -t ed25519 -N '' -C piano-estv-deploy -f "$KEY_DIR/key"
LINE="command=\"$DIR/deploy/deploy.sh\",restrict $(cat "$KEY_DIR/key.pub")"
note "Ligne ajoutée à ~/.ssh/authorized_keys de $VPS_USER (remplace une ancienne clé piano-estv-deploy) :"
note "$LINE"
confirm "L'ajouter ?" || exit 1
printf '%s\n' "$LINE" | on_vps 'umask 077; mkdir -p ~/.ssh; touch ~/.ssh/authorized_keys
  new=$(cat); rest=$(grep -v " piano-estv-deploy$" ~/.ssh/authorized_keys || true)
  { [ -z "$rest" ] || printf "%s\n" "$rest"; printf "%s\n" "$new"; } > ~/.ssh/authorized_keys.new
  cat ~/.ssh/authorized_keys.new > ~/.ssh/authorized_keys; rm ~/.ssh/authorized_keys.new'
HOST_SPEC="$VPS_IP"; [[ "$VPS_PORT" == 22 ]] || HOST_SPEC="[$VPS_IP]:$VPS_PORT"
KNOWN_HOSTS=$(ssh-keygen -F "$HOST_SPEC" | grep -v '^#' || true)
[[ -n "$KNOWN_HOSTS" ]] || { warn "Empreinte du VPS absente de ~/.ssh/known_hosts."; exit 1; }
printf '%s\n' "$KNOWN_HOSTS" > "$KEY_DIR/known_hosts"
say "Essai : on demande une commande interdite, elle doit être refusée."
ANSWER=$(ssh -F /dev/null -i "$KEY_DIR/key" -p "$VPS_PORT" -o IdentitiesOnly=yes -o IdentityAgent=none -o BatchMode=yes \
  -o StrictHostKeyChecking=yes -o UserKnownHostsFile="$KEY_DIR/known_hosts" "$VPS_USER@$VPS_IP" id 2>&1 || true)
[[ "$ANSWER" == *"Commande refusée"* ]] || { warn "Réponse inattendue : $ANSWER"; exit 1; }
pause "Refusée, comme prévu : la clé marche. Entrée pour continuer"

# ──────────────────────────────────────────────────────────────────────────
stage "Enregistrer les secrets GitHub"
say "Dans $REPO_NAME → Settings → Secrets and variables → Actions."
set_secret VPS_IP "$VPS_IP"
set_secret VPS_SSH_KEY "$(cat "$KEY_DIR/key")"
set_secret VPS_KNOWN_HOSTS "$KNOWN_HOSTS"
set_var VPS_USER "$VPS_USER"
set_var VPS_PORT "$VPS_PORT"
ask SITE_URL "Adresse publique du site (Entrée = https://piano.estv.fr) :"
set_var SITE_URL "${SITE_URL:-https://piano.estv.fr}"
if (( ${#SKIPPED[@]} )); then
  warn "Un secret n'a pas pu être enregistré : relance l'assistant quand gh marche (gh auth refresh -s repo)."
  exit 1
fi
rm -f "$KEY_DIR/key"
note "La clé privée n'existe plus que dans GitHub : rien à garder."
pause "Entrée pour continuer"

# ──────────────────────────────────────────────────────────────────────────
stage "Activer et déployer"
say "À partir de maintenant, chaque push sur main sera testé puis mis en ligne."
confirm "Activer, et lancer un premier déploiement ?" || exit 1
set_var DEPLOY_ENABLED true
gh workflow run deploy.yml --ref main
sleep 6
RUN=$(gh run list --workflow deploy.yml --event workflow_dispatch -L 1 --json databaseId -q '.[0].databaseId')
open_url "https://github.com/$REPO_NAME/actions/runs/$RUN"
gh run watch "$RUN" --exit-status --interval 10 >/dev/null && say "Déployé." \
  || warn "Échec : regarde « gh run view $RUN --log-failed ». Le site est resté sur la version précédente."
pause "Entrée pour finir"

finish
}

run_wizard "$@"; exit
